"use client";

import React, { createContext, useContext, useState, useEffect } from 'react';

// Types representing the database tables
export type UserRole = 'admin' | 'barber' | 'client';

export interface User {
    id: string;
    name: string;
    email: string;
    password?: string;
    role: UserRole;
    phone?: string;
    photo?: string;
}

export interface Barber {
    id: string;
    userId: string;
    name: string;
    specialty: string;
    commission: number;
    rating: number;
    reviews: number;
    photo?: string;
    active: boolean;
    workingHours?: string;
}

export interface Service {
    id: string;
    name: string;
    description?: string;
    price: number;
    duration: string;
    icon?: string;
    popular?: boolean;
    active: boolean;
}

export interface ShopConfig {
    name: string;
    logo: string;
    address: string;
    phone: string;
    whatsapp: string;
    email: string;
    workingHours: {
        [key: string]: { start: string; end: string; closed: boolean };
    };
    social: {
        instagram: string;
        facebook: string;
    };
}

export type AppointmentStatus = 'agendado' | 'confirmado' | 'em atendimento' | 'concluido' | 'cancelado';

export interface Appointment {
    id: string;
    clientId: string;
    clientName: string;
    barberId: string;
    barberName: string;
    serviceId: string;
    serviceName: string;
    price: number;
    commission: number;
    date: string;
    time: string;
    status: AppointmentStatus;
    createdAt: string;
}

export interface Promotion {
    id: string;
    tag: string;
    title: string;
    description: string;
    price: number;
    color: string;
    accentBg: string;
    textColor: string;
    active: boolean;
}

interface BarberContextType {
    users: User[];
    services: Service[];
    barbers: Barber[];
    appointments: Appointment[];
    promotions: Promotion[];
    currentUser: User | null;
    shopConfig: ShopConfig;

    // Actions
    login: (email: string, password: string) => User | null;
    logout: () => void;
    register: (name: string, email: string, password: string, role: UserRole) => User | undefined;
    addAppointment: (appointment: Omit<Appointment, 'id' | 'createdAt' | 'commission'>) => void;
    updateAppointmentStatus: (id: string, status: AppointmentStatus) => void;
    addService: (service: Omit<Service, 'id'>) => void;
    updateService: (id: string, service: Partial<Service>) => void;
    removeService: (id: string) => void;
    addBarber: (barber: Omit<Barber, 'id' | 'rating' | 'reviews' | 'active'> & { email: string; password?: string }) => void;
    updateBarber: (id: string, data: Partial<Barber>) => void;
    removeBarber: (id: string) => void;
    updateUser: (id: string, data: Partial<User>) => void;
    updateShopConfig: (config: Partial<ShopConfig>) => void;
    addPromotion: (promo: Omit<Promotion, 'id'>) => void;
    updatePromotion: (id: string, data: Partial<Promotion>) => void;
    removePromotion: (id: string) => void;
    resetToSeed: () => void;
}

const BarberContext = createContext<BarberContextType | undefined>(undefined);

export function BarberProvider({ children }: { children: React.ReactNode }) {
    const [users, setUsers] = useState<User[]>([]);
    const [services, setServices] = useState<Service[]>([]);
    const [barbers, setBarbers] = useState<Barber[]>([]);
    const [appointments, setAppointments] = useState<Appointment[]>([]);
    const [promotions, setPromotions] = useState<Promotion[]>([]);
    const [currentUser, setCurrentUser] = useState<User | null>(null);
    const [shopConfig, setShopConfig] = useState<ShopConfig>({
        name: "Marciel Barber Shop",
        logo: "",
        address: "Rua das Tesouras, 123 - Centro",
        phone: "(00) 0000-0000",
        whatsapp: "(00) 00000-0000",
        email: "contato@marcielbarber.com",
        workingHours: {
            "Segunda": { start: "08:00", end: "18:00", closed: false },
            "Terça": { start: "08:00", end: "18:00", closed: false },
            "Quarta": { start: "08:00", end: "18:00", closed: false },
            "Quinta": { start: "08:00", end: "18:00", closed: false },
            "Sexta": { start: "08:00", end: "18:00", closed: false },
            "Sábado": { start: "08:00", end: "16:00", closed: false },
            "Domingo": { start: "00:00", end: "00:00", closed: true }
        },
        social: { instagram: "@marcielbarber", facebook: "marcielbarbershop" }
    });

    // Initial Load and Seed
    useEffect(() => {
        const savedUsers = localStorage.getItem('mbs_users');
        const savedBarbers = localStorage.getItem('mbs_barbers');
        const savedServices = localStorage.getItem('mbs_services');
        const savedApps = localStorage.getItem('mbs_appointments');
        const savedPromos = localStorage.getItem('mbs_promotions');
        const savedCurrentUser = localStorage.getItem('mbs_current_user');
        const savedShopConfig = localStorage.getItem('mbs_shop_config');

        // Load existing data
        const loadedUsers = savedUsers ? JSON.parse(savedUsers) : [];
        const loadedBarbers = savedBarbers ? JSON.parse(savedBarbers) : [];
        const loadedServices = savedServices ? JSON.parse(savedServices) : [];
        const loadedPromos = savedPromos ? JSON.parse(savedPromos) : [];

        // Seed data if missing
        const hasAdmin = loadedUsers.some((u: any) => u.email === 'admin@teste.com');

        if (!hasAdmin) {
            const seedUsers: User[] = [
                { id: 'u_admin', name: 'Marciel Santos', email: 'admin@teste.com', password: '123456', role: 'admin' },
                { id: 'u_client', name: 'Cliente Teste', email: 'cliente@teste.com', password: '123456', role: 'client' },
                { id: 'u_barber', name: 'Barbeiro Teste', email: 'barbeiro@teste.com', password: '123456', role: 'barber' },
                ...loadedUsers
            ];
            const seedBarbers: Barber[] = [
                { id: 'b_marciel', userId: 'u_admin', name: 'Marciel Santos', specialty: 'Master Barber', commission: 60, rating: 5.0, reviews: 0, active: true },
                { id: 'b_test', userId: 'u_barber', name: 'Barbeiro Teste', specialty: 'Corte Social', commission: 40, rating: 4.8, reviews: 12, active: true },
                ...loadedBarbers
            ];
            const seedServices: Service[] = [
                { id: 's1', name: 'Corte Degradê', description: 'Corte moderno com sombreado perfeito.', price: 45, duration: '40 min', icon: '✂️', popular: true, active: true },
                { id: 's2', name: 'Barba Trimmed', description: 'Alinhamento e hidratação da barba.', price: 35, duration: '25 min', icon: '🪒', active: true },
                { id: 's3', name: 'Corte + Barba', description: 'Combo completo para renovar o visual.', price: 70, duration: '60 min', icon: '💈', active: true },
                ...loadedServices
            ];
            const seedPromos: Promotion[] = [
                {
                    id: 'p1',
                    tag: 'Especial de Primavera',
                    title: 'Corte + Hidratação',
                    description: 'Revitalize seu cabelo com desconto.',
                    price: 59.90,
                    color: 'from-[#1A1100] to-black',
                    accentBg: 'bg-[#D4AF37]',
                    textColor: 'text-black',
                    active: true
                },
                ...loadedPromos
            ];

            setUsers(seedUsers);
            setBarbers(seedBarbers);
            setServices(seedServices);
            setPromotions(seedPromos);

            localStorage.setItem('mbs_users', JSON.stringify(seedUsers));
            localStorage.setItem('mbs_barbers', JSON.stringify(seedBarbers));
            localStorage.setItem('mbs_services', JSON.stringify(seedServices));
            localStorage.setItem('mbs_promotions', JSON.stringify(seedPromos));
        } else {
            setUsers(loadedUsers);
            setBarbers(loadedBarbers);
            setServices(loadedServices);
            setPromotions(loadedPromos);
        }

        if (savedApps) setAppointments(JSON.parse(savedApps));
        if (savedCurrentUser) setCurrentUser(JSON.parse(savedCurrentUser));
        if (savedShopConfig) setShopConfig(JSON.parse(savedShopConfig));
    }, []);

    const resetToSeed = () => {
        localStorage.removeItem('mbs_users');
        localStorage.removeItem('mbs_barbers');
        localStorage.removeItem('mbs_services');
        localStorage.removeItem('mbs_appointments');
        localStorage.removeItem('mbs_promotions');
        localStorage.removeItem('mbs_current_user');
        localStorage.removeItem('mbs_shop_config');
        window.location.reload();
    };

    // Sync to LocalStorage
    useEffect(() => { localStorage.setItem('mbs_users', JSON.stringify(users)); }, [users]);
    useEffect(() => { localStorage.setItem('mbs_barbers', JSON.stringify(barbers)); }, [barbers]);
    useEffect(() => { localStorage.setItem('mbs_services', JSON.stringify(services)); }, [services]);
    useEffect(() => { localStorage.setItem('mbs_appointments', JSON.stringify(appointments)); }, [appointments]);
    useEffect(() => { localStorage.setItem('mbs_promotions', JSON.stringify(promotions)); }, [promotions]);
    useEffect(() => { localStorage.setItem('mbs_shop_config', JSON.stringify(shopConfig)); }, [shopConfig]);

    const login = (email: string, password: string) => {
        const user = users.find(u => u.email.toLowerCase() === email.toLowerCase() && u.password === password);
        if (user) {
            setCurrentUser(user);
            localStorage.setItem('mbs_current_user', JSON.stringify(user));
            return user;
        }
        return null;
    };

    const register = (name: string, email: string, password: string, role: UserRole) => {
        const newUser: User = { id: 'u' + Date.now(), name, email, password, role };
        setUsers(prev => [...prev, newUser]);
        setCurrentUser(newUser);
        localStorage.setItem('mbs_current_user', JSON.stringify(newUser));
        return newUser;
    };

    const logout = () => {
        setCurrentUser(null);
        localStorage.removeItem('mbs_current_user');
    };

    const addAppointment = (data: Omit<Appointment, 'id' | 'createdAt' | 'commission'>) => {
        const barber = barbers.find(b => b.id === data.barberId);
        const commissionVal = (data.price * (barber?.commission || 40)) / 100;
        const newApp: Appointment = {
            ...data,
            id: 'app' + Date.now(),
            createdAt: new Date().toISOString(),
            commission: commissionVal
        };
        setAppointments(prev => [newApp, ...prev]);
    };

    const updateAppointmentStatus = (id: string, status: AppointmentStatus) => {
        setAppointments(prev => prev.map(app => app.id === id ? { ...app, status } : app));
    };

    const addService = (data: Omit<Service, 'id'>) => {
        const newService: Service = { ...data, id: 's' + Date.now() };
        setServices(prev => [...prev, newService]);
    };

    const updateService = (id: string, data: Partial<Service>) => {
        setServices(prev => prev.map(s => s.id === id ? { ...s, ...data } : s));
    };

    const removeService = (id: string) => {
        setServices(prev => prev.filter(s => s.id !== id));
    };

    const addBarber = (data: Omit<Barber, 'id' | 'rating' | 'reviews' | 'active'> & { email: string; password?: string }) => {
        const userId = 'u' + Date.now();
        const newUser: User = {
            id: userId,
            name: data.name,
            email: data.email,
            password: data.password || '123456',
            role: 'barber'
        };
        const newBarber: Barber = {
            ...data,
            id: 'b' + Date.now(),
            userId,
            rating: 5.0,
            reviews: 0,
            active: true
        } as Barber;
        setUsers(prev => [...prev, newUser]);
        setBarbers(prev => [...prev, newBarber]);
    };

    const updateBarber = (id: string, data: Partial<Barber>) => {
        setBarbers(prev => prev.map(b => b.id === id ? { ...b, ...data } : b));
    };

    const removeBarber = (id: string) => {
        const barber = barbers.find(b => b.id === id);
        if (barber) {
            setUsers(prev => prev.filter(u => u.id !== barber.userId));
        }
        setBarbers(prev => prev.filter(b => b.id !== id));
    };

    const updateUser = (id: string, data: Partial<User>) => {
        setUsers(prev => prev.map(u => u.id === id ? { ...u, ...data } : u));
        if (currentUser?.id === id) {
            const updated = { ...currentUser, ...data } as User;
            setCurrentUser(updated);
            localStorage.setItem('mbs_current_user', JSON.stringify(updated));
        }
    };

    const updateShopConfig = (data: Partial<ShopConfig>) => {
        setShopConfig(prev => ({ ...prev, ...data }));
    };

    const addPromotion = (data: Omit<Promotion, 'id'>) => {
        const newPromo: Promotion = { ...data, id: 'p' + Date.now() };
        setPromotions(prev => [...prev, newPromo]);
    };

    const updatePromotion = (id: string, data: Partial<Promotion>) => {
        setPromotions(prev => prev.map(p => p.id === id ? { ...p, ...data } : p));
    };

    const removePromotion = (id: string) => {
        setPromotions(prev => prev.filter(p => p.id !== id));
    };

    return (
        <BarberContext.Provider value={{
            users, services, barbers, appointments, promotions, currentUser, shopConfig,
            login, logout, register, addAppointment, updateAppointmentStatus,
            addService, updateService, removeService, addBarber, updateBarber, removeBarber, updateUser, updateShopConfig, resetToSeed,
            addPromotion, updatePromotion, removePromotion
        }}>
            {children}
        </BarberContext.Provider>
    );
}

export function useBarber() {
    const context = useContext(BarberContext);
    if (!context) throw new Error('useBarber must be used within a BarberProvider');
    return context;
}
